<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';
use Annam\{Database,Store,Resources,Pricing,Orders,Billing,HttpError};
if(PHP_SAPI!=='cli'||!preg_match('~^sqlite:.*(?:test|preview).*~',getenv('DATABASE_DSN')?:''))exit(1);
$db=new Database();
if(($argv[1]??'')==='worker'){
 try{$store=new Store($db);if($argv[2]==='bill')$result=(new Billing($store))->issue((int)$argv[3]);else{$item=$store->item((int)$argv[3]);$line=Pricing::line($item,1);$line['meal_key']='lunch';$quote=Pricing::totals([$line],0,$store->profile())+['kind'=>'scheduled','zone'=>[],'date'=>date('Y-m-d'),'slot'=>$store->slots()[0]];$result=(new Orders($store))->create($quote,['name'=>'Concurrent fixture','phone'=>'919999999999','payment_method'=>'manual','line1'=>'Test address','city'=>'Chennai','pincode'=>'600005'],$argv[4],'web');}echo json_encode(['id'=>$result['id']]);exit(0);}catch(HttpError $e){echo json_encode(['status'=>$e->status]);exit(0);}
}
function wave(array $commands):array {$running=[];foreach($commands as $command){$process=proc_open([PHP_BINARY,__FILE__,'worker',...$command],[1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($process))throw new RuntimeException('Could not start isolated writer.');$running[]=[$process,$pipes];}$result=[];foreach($running as [$process,$pipes]){$output=stream_get_contents($pipes[1]);$error=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($process)!==0)throw new RuntimeException('Concurrent worker failed: '.$error);$result[]=json_decode($output,true,32,JSON_THROW_ON_ERROR);}return $result;}
function assertThat(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
$tenant=null;
try{
 $slug='sqlite-race-'.bin2hex(random_bytes(5));$template=$db->one('SELECT * FROM tenancy_tenantconfig LIMIT 1');$profile=$db->one('SELECT * FROM tenancy_billingprofile LIMIT 1');$tenant=(int)$db->one('INSERT INTO tenancy_tenant(slug,name,primary_domain,status,created_at) VALUES(?,?,?,?,?) RETURNING id',[$slug,'Concurrency fixture','','active',date('c')])['id'];
 foreach(['tenancy_tenantconfig'=>$template,'tenancy_billingprofile'=>$profile] as $table=>$row){unset($row['id']);$row['tenant_id']=$tenant;if($table==='tenancy_billingprofile'){$row['gst_mode']='unregistered';$row['tax_rate']='0.00';$row['round_total']=false;$row['bill_timing']='on_delivery';}$fields=array_keys($row);$db->rows('INSERT INTO '.$table.'('.implode(',',array_map(fn($n)=>'"'.$n.'"',$fields)).') VALUES('.implode(',',array_fill(0,count($fields),'?')).')',array_values($row));}
 putenv('STORE_SLUG='.$slug);$store=new Store($db);$resources=new Resources($store);$slot=$resources->save('slots',null,['key'=>'lunch','label'=>'Lunch','order_cutoff'=>'23:59:59','active'=>1]);$item=$resources->save('dishes',null,['name'=>'Last portion','price'=>'110.10','fulfilment'=>'scheduled','active'=>1,'in_stock'=>1,'is_veg'=>1]);$store->saveMenu(date('Y-m-d'),$slot,[$item],0);$db->rows('UPDATE catalog_menuschedule SET qty_limit=1 WHERE tenant_id=?',[$tenant]);
 $results=wave([['order',(string)$item,'race-a'],['order',(string)$item,'race-b']]);assertThat(count(array_filter($results,fn($r)=>isset($r['id'])))===1,'Both buyers got the last portion.');assertThat((int)$db->one('SELECT qty_sold FROM catalog_menuschedule WHERE tenant_id=?',[$tenant])['qty_sold']===1,'Stock was oversold.');echo "PASS simultaneous buyers cannot oversell the last portion\n";
 $db->rows('UPDATE catalog_menuschedule SET qty_limit=NULL WHERE tenant_id=?',[$tenant]);$results=wave([['order',(string)$item,'same-submit'],['order',(string)$item,'same-submit']]);assertThat($results[0]['id']===$results[1]['id'],'Concurrent retry created duplicate orders.');$orderId=(int)$results[0]['id'];echo "PASS simultaneous duplicate submission creates one order\n";
 (new Orders($store))->confirm($orderId,'fixture','manual-receipt',true);$results=wave([['bill',(string)$orderId],['bill',(string)$orderId]]);assertThat($results[0]['id']===$results[1]['id'],'Concurrent bill issue duplicated an invoice.');assertThat((int)$db->one('SELECT COUNT(*) AS n FROM billing_invoice WHERE tenant_id=? AND order_id=?',[$tenant,$orderId])['n']===1,'Multiple invoices issued.');echo "PASS simultaneous invoice requests allocate one immutable bill\n";
}finally{
 if($tenant)$db->transaction(function()use($db,$tenant){foreach(json_decode(file_get_contents(ANNAM_ROOT.'/resources/sqlite-types.json'),true) as $table=>$fields)if(isset($fields['tenant_id']))$db->rows('DELETE FROM "'.$table.'" WHERE tenant_id=?',[$tenant]);$db->rows('DELETE FROM tenancy_tenant WHERE id=?',[$tenant]);});
}
